{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울시 공영주차장에서 한부모가족이라는 사유로 할인받을 수 있는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 주차장 설치 및 관리 조례 제7조제1항제7호의2에 따라, 「한부모가족지원법」에 따른 지원대상자로서 한부모가족증명서를 제시하면 주차요금의 100분의 50을 할인받을 수 있습니다. 질문자는 한부모가족 지원대상자로 선정되었고 증명서도 있다고 하였으므로, 해당 요건을 충족하면 공영주차장에서 한부모가족 사유로 할인이 가능합니다.",
          "b_ids": "주차장:제7조제1항제7호의2"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
